L=open(sys.argv[1]).read().splitlines()
for i in range(1680,1720):
    e=json.loads(L[i]); t=e.get("type")
    if t=="assistant":
        for b in e["message"]["content"]:
            if b.get("type")=="text": print(i,"TEXT",b["text"][:400])
            if b.get("type")=="tool_use": print(i,"TOOL",json.dumps(b.get("input"))[:300])
